-- 057: model proyektor Panasonic yang dipakai tim (PT-MZ882 + lensa, PT-LMX460, PT-TMZ400) di Pustaka.
--
-- Angka diambil dari koefisien Panasonic Throw Distance Calculator 2.79 (rumus L = A x diagonal - B di ujung
-- wide & tele), bukan brosur: throw ratio brosur PT-MZ882 1,61-2,76 vs rumus kalkulator 1,639-2,788, dan b
-- (5-21 cm untuk lensa-lensa ini) tidak ada di brosur sama sekali. Tanpa keduanya jarak lempar meleset
-- beberapa cm hingga puluhan cm dari simulasi Panasonic. Diuji di uji/proyektor-panasonic-data.ts.
--
-- Lens shift: poligon daerah shift Panasonic (segi delapan - shift vertikal & horizontal penuh tidak bisa
-- bersamaan). PT-LMX460, PT-TMZ400 & ET-ELW21 tanpa lens shift: offset gambar tetap.
--
-- Hanya menambah baris yang belum ada (nama + jenis), jadi aman dijalankan ulang.
insert into public.tools_pustaka (jenis, nama, data, diubah_oleh_nama)
select v.jenis, v.nama, v.data::jsonb, 'Bawaan'
from (values
  ('proyektor', 'Panasonic PT-MZ882 + lensa standar ET-ELS20', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":1.63911,"throwMaks":2.78771,"koreksiJarak":0.054882,"koreksiJarakTele":0.048228,"shiftAtas":67,"shiftBawah":67,"shiftHorizontal":35,"poligonShift":"-0.5,1.17; 0.5,1.17; 0.85,0.5; 0.85,-0.5; 0.5,-1.17; -0.5,-1.17; -0.85,-0.5; -0.85,0.5","kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.035305 × diagonal − 0.054882 (wide), 0.060045 × diagonal − 0.048228 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-MZ882 + ET-ELU20 (ultra short throw)', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":0.33827,"throwMaks":0.36417,"koreksiJarak":0.029388,"koreksiJarakTele":0.034616,"shiftAtas":50,"shiftBawah":50,"shiftHorizontal":24,"poligonShift":"-0.5,1; 0.5,1; 0.74,0.5; 0.74,-0.5; 0.5,-1; -0.5,-1; -0.74,-0.5; -0.74,0.5","kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.007286 × diagonal − 0.029388 (wide), 0.007844 × diagonal − 0.034616 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-MZ882 + ET-ELW22', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":0.81415,"throwMaks":1.00919,"koreksiJarak":0.04846,"koreksiJarakTele":0.045477,"shiftAtas":60,"shiftBawah":60,"shiftHorizontal":30,"poligonShift":"-0.5,1.1; 0.5,1.1; 0.8,0.5; 0.8,-0.5; 0.5,-1.1; -0.5,-1.1; -0.8,-0.5; -0.8,0.5","kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.017536 × diagonal − 0.04846 (wide), 0.021737 × diagonal − 0.045477 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-MZ882 + ET-ELW20', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":1.24499,"throwMaks":1.6951,"koreksiJarak":0.055497,"koreksiJarakTele":0.0534,"shiftAtas":67,"shiftBawah":67,"shiftHorizontal":35,"poligonShift":"-0.5,1.17; 0.5,1.17; 0.85,0.5; 0.85,-0.5; 0.5,-1.17; -0.5,-1.17; -0.85,-0.5; -0.85,0.5","kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.026816 × diagonal − 0.055497 (wide), 0.036511 × diagonal − 0.0534 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-MZ882 + ET-ELT22', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":2.79036,"throwMaks":4.5499,"koreksiJarak":0.114022,"koreksiJarakTele":0.112874,"shiftAtas":67,"shiftBawah":67,"shiftHorizontal":35,"poligonShift":"-0.5,1.17; 0.5,1.17; 0.85,0.5; 0.85,-0.5; 0.5,-1.17; -0.5,-1.17; -0.85,-0.5; -0.85,0.5","kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.060102 × diagonal − 0.114022 (wide), 0.098001 × diagonal − 0.112874 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-MZ882 + ET-ELT23', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":4.55979,"throwMaks":7.24244,"koreksiJarak":0.212284,"koreksiJarakTele":0.210772,"shiftAtas":67,"shiftBawah":67,"shiftHorizontal":35,"poligonShift":"-0.5,1.17; 0.5,1.17; 0.85,0.5; 0.85,-0.5; 0.5,-1.17; -0.5,-1.17; -0.85,-0.5; -0.85,0.5","kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.098214 × diagonal − 0.212284 (wide), 0.155996 × diagonal − 0.210772 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-MZ882 + ET-ELW21 (fixed)', '{"merek":"Panasonic","lumen":8200,"resolusi":"WUXGA","throwMin":0.79752,"throwMaks":0.79752,"koreksiJarak":0.057678,"shiftAtas":0,"shiftBawah":0,"shiftHorizontal":0,"offsetTetap":0,"kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.017178 × diagonal − 0.057678 (wide). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-LMX460', '{"merek":"Panasonic","lumen":4600,"resolusi":"XGA","throwMin":1.481,"throwMaks":1.78563,"koreksiJarak":0.0265,"shiftAtas":0,"shiftBawah":0,"shiftHorizontal":0,"offsetTetap":34.62,"kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 4:3: L = 0.030094 × diagonal − 0.0265 (wide), 0.036284 × diagonal − 0.0265 (tele). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}'),
  ('proyektor', 'Panasonic PT-TMZ400 (short throw)', '{"merek":"Panasonic","lumen":4000,"resolusi":"WUXGA","throwMin":0.44505,"throwMaks":0.44505,"koreksiJarak":0.0332,"shiftAtas":0,"shiftBawah":0,"shiftHorizontal":0,"offsetTetap":60.03,"kontras":3000000,"sumber":"laser","catatan":"Dari Panasonic Throw Distance Calculator 2.79, rasio 16:10: L = 0.009586 × diagonal − 0.0332 (wide). TR & b di sini = rumus kalkulator itu, bukan angka brosur."}')
) as v(jenis, nama, data)
where not exists (select 1 from public.tools_pustaka t where t.jenis = v.jenis and t.nama = v.nama);
